}

fn sutherland_hodgman(subject: &[Point64], clip: &[Point64]) -> Path64 {
    if subject.is_empty() || clip.is_empty() {
        return Vec::new();
    }

    let mut output: Vec<(f64, f64)> = subject.iter().map(|p| (p.x as f64, p.y as f64)).collect();
    let clip_points: Vec<(f64, f64)> = clip.iter().map(|p| (p.x as f64, p.y as f64)).collect();

    for edge_idx in 0..clip_points.len() {
        if output.is_empty() {
            break;
        }

        let a = clip_points[edge_idx];
        let b = clip_points[(edge_idx + 1) % clip_points.len()];
        let input = output;
        output = Vec::new();

        let mut prev = *input.last().unwrap();
        for curr in input {
            let curr_inside = cross(b.0 - a.0, b.1 - a.1, curr.0 - a.0, curr.1 - a.1) >= -1e-9;
            let prev_inside = cross(b.0 - a.0, b.1 - a.1, prev.0 - a.0, prev.1 - a.1) >= -1e-9;

            if curr_inside {
                if !prev_inside {
                    output.push(line_intersection(prev, curr, a, b));
                }
                output.push(curr);
            } else if prev_inside {
                output.push(line_intersection(prev, curr, a, b));
            }
            prev = curr;
        }
    }

    output
        .into_iter()
        .map(|(x, y)| Point64::new(round_away_from_zero(x), round_away_from_zero(y)))
        .collect()
}

fn line_intersection(
    a1: (f64, f64),
    a2: (f64, f64),
    b1: (f64, f64),
    b2: (f64, f64),
) -> (f64, f64) {
    let a = a1.0 * a2.1 - a1.1 * a2.0;
    let b = b1.0 * b2.1 - b1.1 * b2.0;
    let den = (a1.0 - a2.0) * (b1.1 - b2.1) - (a1.1 - a2.1) * (b1.0 - b2.0);
    let x = (a * (b1.0 - b2.0) - (a1.0 - a2.0) * b) / den;
    let y = (a * (b1.1 - b2.1) - (a1.1 - a2.1) * b) / den;
    (x, y)
}

fn outward_normals(path: &[Point64]) -> Vec<PointD> {
    let mut normals = Vec::with_capacity(path.len());
    for idx in 0..path.len() {
        let p1 = path[idx];
        let p2 = path[(idx + 1) % path.len()];
        let dx = (p2.x - p1.x) as f64;
        let dy = (p2.y - p1.y) as f64;
        let len = (dx * dx + dy * dy).sqrt();
        normals.push(PointD::new(dy / len, -dx / len));
    }
    normals
}

fn arc_step_count(delta: f64, angle: f64) -> usize {
    let radius = delta.abs();
    if radius == 0.0 {
        return 0;
    }
    let arc_tolerance = 0.25_f64.min(radius);
    let steps_per_circle = if arc_tolerance >= radius {
        4.0
    } else {
        PI / (1.0 - arc_tolerance / radius).acos()
    };
    ((steps_per_circle * angle.abs() / (2.0 * PI)).round() as usize).max(1)
}

fn rotate(vec: PointD, angle: f64) -> PointD {
    let s = angle.sin();
    let c = angle.cos();
    PointD::new(vec.x * c - vec.y * s, vec.x * s + vec.y * c)
}

fn dedup_path(path: &mut Path64) {
    path.dedup();
    if path.len() > 1 && path.first() == path.last() {
        path.pop();
    }
}

fn offset_round_polygon(path: &[Point64], delta: i64) -> Path64 {
    if path.len() < 3 || delta == 0 {
        return path.to_vec();
    }

    let delta_f = delta as f64;
    let normals = outward_normals(path);
    let mut out = Vec::new();

    for idx in 0..path.len() {
        let prev_edge = if idx == 0 { path.len() - 1 } else { idx - 1 };
        let prev_normal = normals[prev_edge];
        let curr_normal = normals[idx];
        let sin_a = cross(prev_normal.x, prev_normal.y, curr_normal.x, curr_normal.y);
        let cos_a = dot(prev_normal.x, prev_normal.y, curr_normal.x, curr_normal.y);
        let angle = sin_a.atan2(cos_a);
        let steps = arc_step_count(delta_f, angle);
        let step_angle = angle / steps as f64;

        for step in 0..steps {
            let n = rotate(prev_normal, step_angle * step as f64);
            out.push(Point64::new(
                round_away_from_zero(path[idx].x as f64 + n.x * delta_f),
                round_away_from_zero(path[idx].y as f64 + n.y * delta_f),
            ));
        }
        out.push(Point64::new(
            round_away_from_zero(path[idx].x as f64 + curr_normal.x * delta_f),
            round_away_from_zero(path[idx].y as f64 + curr_normal.y * delta_f),
        ));
    }

    dedup_path(&mut out);
    if out.len() < 3 || signed_area(out.as_slice()) <= 0.0 {
        return Vec::new();
    }
    out
}

fn signed_area(path: &[Point64]) -> f64 {
    let mut sum = 0_f64;
    for idx in 0..path.len() {
        let p1 = path[idx];
        let p2 = path[(idx + 1) % path.len()];
        sum += (p1.x as f64) * (p2.y as f64) - (p2.x as f64) * (p1.y as f64);
    }
    sum * 0.5
}

pub fn intersect(subjects: Paths64, clips: Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut results = Vec::new();
    for subject in &subjects {
        for clip in &clips {
            let mut subj = subject.clone();
            let mut clp = clip.clone();
            ensure_ccw(&mut subj);
            ensure_ccw(&mut clp);
            let clipped = sutherland_hodgman(&subj, &clp);
            if clipped.len() >= 3 {
                results.push(clipped);
            }
        }
    }
    results
}

pub fn inflate_paths(paths: Paths64, delta: i64, _join: JoinType, _end: EndType) -> Paths64 {
    let mut out = Vec::new();
    for path in paths {
        let mut poly = path;
        ensure_ccw(&mut poly);
        let offset = offset_round_polygon(&poly, delta);
        if offset.len() >= 3 {
            out.push(offset);
        }
    }
    out
}

pub fn area(path: &[Point64]) -> f64 {
    signed_area(path).abs()
}

pub fn get_bounds(paths: &[Path64]) -> Rect64 {
    let mut iter = paths.iter().flat_map(|path| path.iter());
    let first = iter.next().unwrap_or(&Point64::new(0, 0));
    let mut left = first.x;
    let mut right = first.x;
    let mut top = first.y;
    let mut bottom = first.y;

    for point in iter {
        left = left.min(point.x);
        right = right.max(point.x);
        top = top.min(point.y);
        bottom = bottom.max(point.y);
    }

    Rect64 {
        left,
        top,
        right,
        bottom,
    }
}

